    53  GF_Err RTSP_UnpackURL(char *sURL, char Server[1024], u16 *Port, char Service[1024], Bool *useTCP, char User[1024], char Pass[1024])
    54  {
    55          char schema[10], *test, text[1024], *retest, *sep, *service_start;
    56          u32 i, len;
    57          Bool is_ipv6;
    58          if (!sURL) return GF_BAD_PARAM;
    59
    60          Server[0] = 0;
    61          Service[0] = 0;
    62          User[0] = 0;
    63          Pass[0] = 0;
    64
    65          *Port = 0;
    66          *useTCP = GF_FALSE;
    67
    68          if (!strchr(sURL, ':')) return GF_BAD_PARAM;
    69
    70          sep = strchr(sURL, '?');
    71          if (sep) sep[0] = 0;
    72          //extract the schema
    73          i = 0;
    74          while (i<=strlen(sURL)) {
    75                  if (i==10) return GF_BAD_PARAM;
    76                  if (sURL[i] == ':') goto found;
    77                  schema[i] = sURL[i];
    78                  i += 1;
    79          }
    80          if (sep) sep[0] = '?';
    81          return GF_BAD_PARAM;
    82
    83  found:
    84          schema[i] = 0;
    85          if (stricmp(schema, "rtsp") && stricmp(schema, "rtspu") && stricmp(schema, "rtsph")  && stricmp(schema, "rtsps") && stricmp(schema, "satip")) return GF_URL_ERROR;
    86          //check for user/pass - not allowed
    87          /*
    88                  test = strstr(sURL, "@");
    89                  if (test) return GF_NOT_SUPPORTED;
    90          */
    91          test = strstr(sURL, "://");
    92          if (!test) {
    93                  if (sep) sep[0] = '?';
    94                  return GF_URL_ERROR;
    95          }
    96          test += 3;
    97          //check for service
    98          retest = strstr(test, "/");
    99          if (!retest) {
   100                  if (sep) sep[0] = '?';
   101                  return GF_URL_ERROR;
   102          }
   103          if (!stricmp(schema, "rtsp") || !stricmp(schema, "satip") || !stricmp(schema, "rtsph") || !stricmp(schema, "rtsps"))
   104                  *useTCP = GF_TRUE;
   105
   106          service_start = retest;
   107          //check for port
   108          char *port = strrchr(test, ':');
   109          retest = (port<retest) ? port : NULL;
   110          /*IPV6 address*/
   111          if (retest && strchr(retest, ']')) retest = NULL;
   112
   113          if (retest && strstr(retest, "/")) {
   114                  retest += 1;
   115                  i=0;
   116                  while (i<strlen(retest) && i<1023) {
   117                          if (retest[i] == '/') break;
   118                          text[i] = retest[i];
   119                          i += 1;
   120                  }
   121                  text[i] = 0;
   122                  *Port = atoi(text);
   123          }
   124
   125          char *sep_auth = strchr(test, '@');
   126          if (sep_auth>service_start) sep_auth=NULL;
   127          if (sep_auth) {
   128                  sep_auth[0] = 0;
   129                  char *psep = strchr(test, ':');
   130                  if (psep) psep[0] = 0;
   131                  strncpy(User, test, 1023);
   132                  User[1023]=0;
   133                  if (psep) {
   134                          strncpy(Pass, psep+1, 1023);
   135                          Pass[1023]=0;
   136                          if (psep) psep[0] = ':';
   137                  }
   138
   139                  sep_auth[0] = '@';
   140                  test = sep_auth+1;
   141          }
   142
   143          //get the server name
   144          is_ipv6 = GF_FALSE;
   145          len = (u32) strlen(test);
   146          i=0;
   147          while (i<len) {
   148                  if (test[i]=='[') is_ipv6 = GF_TRUE;
   149                  else if (test[i]==']') is_ipv6 = GF_FALSE;
   150                  if ( (test[i] == '/') || (!is_ipv6 && (test[i] == ':')) ) break;
   151                  text[i] = test[i];
   152                  i += 1;
   153          }
   154          text[MIN(i, GF_ARRAY_LENGTH(text)-1)] = 0;
   155          strncpy(Server, text, 1024);
   156          Server[1023]=0;
   157          if (sep) sep[0] = '?';
   158
   159          if (service_start) {
   160                  strncpy(Service, service_start+1, 1023);
   161                  Service[1023]=0;
   162          } else {
   163                  Service[0]=0;
   164          }
   165          return GF_OK;
   166  }
